findings.codeql_raw_query:
/**
 * @name User-controlled import via YAML node value
 * @description Tracing flow from YAML node values to __import__ calls in constructor.py
 * @kind path-problem
 * @problem.severity error
 * @id py/yaml-unsafe-import
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module YamlUnsafeImportConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: Accessing .value on a parameter named 'node' in lib/yaml/constructor.py
    exists(DataFlow::ParameterNode p, DataFlow::AttrRead read |
      p.getParameter().getName() = "node" and
      p.getLocation().getFile().getShortName() = "constructor.py" and
      read.getObject().getALocalSource() = p and
      read.getAttributeName() = "value" and
      source = read
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: Argument 0 of __import__
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("__import__").getACall() and
      sink = call.getArg(0)
    )
  }
}

module YamlUnsafeImportFlow = TaintTracking::Global<YamlUnsafeImportConfig>;
import YamlUnsafeImportFlow::PathGraph

from YamlUnsafeImportFlow::PathNode source, YamlUnsafeImportFlow::PathNode sink
where YamlUnsafeImportFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Arbitrary module import from $@.", source.getNode(), "YAML node value"
